<?php
require __DIR__.'/../includes/functions.php'; require_login('admin');$result=[];$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(empty($_FILES['csv']['tmp_name']))$error='فایل CSV را انتخاب کنید.';else{$fh=fopen($_FILES['csv']['tmp_name'],'r');$header=fgetcsv($fh);$header=array_map('trim',$header?:[]);$required=['name','mobile','password'];if(array_diff($required,$header))$error='ستون‌های name,mobile,password الزامی هستند.';else{while(($row=fgetcsv($fh))!==false){$data=array_combine($header,$row);if(!$data||trim($data['name']??'')===''||strlen((string)($data['password']??''))<6){$result[]=['status'=>'خطا','message'=>'نام یا رمز نامعتبر'];continue;}try{db()->prepare("INSERT INTO users(mobile,password_hash,role,name) VALUES(?,?, 'student',?)")->execute([trim($data['mobile']),password_hash($data['password'],PASSWORD_DEFAULT),trim($data['name'])]);$result[]=['status'=>'موفق','message'=>$data['name']];}catch(PDOException $e){$result[]=['status'=>'تکراری/خطا','message'=>$data['mobile']];}}fclose($fh);audit('bulk_import','students',null,count($result).' rows');}}}
layout_start('ورود گروهی');?><div class="page-head"><div><p class="eyebrow">مدیریت دانش‌آموزان</p><h1>ورود گروهی CSV</h1></div><a class="button secondary" href="<?=e(url('/admin/index.php'))?>">بازگشت</a></div><div class="card"><p>فایل CSV با ستون‌های انگلیسی زیر بسازید:</p><pre>name,mobile,password</pre><p class="muted">رمز اولیه حداقل ۶ کاراکتر باشد. رمزها پس از ورود فقط به‌صورت هش‌شده ذخیره می‌شوند.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>فایل CSV<input type="file" name="csv" accept=".csv,text/csv" required></label><button class="button">شروع ورود</button></form></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($result):?><div class="card table-wrap"><h2>گزارش ورود</h2><table><tr><th>وضعیت</th><th>رکورد</th></tr><?php foreach($result as $r):?><tr><td><?=e($r['status'])?></td><td><?=e($r['message'])?></td></tr><?php endforeach;?></table></div><?php endif;?><?php layout_end(); ?>
